package vn.aicrm.retail;

import java.util.*;
import com.fasterxml.jackson.databind.JsonNode;
import org.springframework.web.bind.annotation.*;
import org.springframework.security.core.Authentication;
import org.springframework.http.*;
import org.springframework.web.multipart.MultipartFile;
import static vn.aicrm.retail.RetailAccess.*;

@RestController
@RequestMapping("/api/v1/retail")
public class RetailController {
  private final RetailAccess r;private final RetailCommands commands;private final RetailCatalog catalog;private final RetailDocuments documents;private final RetailInventory inventory;private final RetailFinance finance;private final RetailOperations operations;private final RetailImport imports;private final RetailCommissions commissions;
  public RetailController(RetailAccess r,RetailCommands commands,RetailCatalog catalog,RetailDocuments documents,RetailInventory inventory,RetailFinance finance,RetailOperations operations,RetailImport imports,RetailCommissions commissions){this.r=r;this.commands=commands;this.catalog=catalog;this.documents=documents;this.inventory=inventory;this.finance=finance;this.operations=operations;this.imports=imports;this.commissions=commissions;}
  @GetMapping("/uom-conversions") Object uomConversions(Authentication a){r.require(a,"SETUP");return Map.of("units",r.db.queryForList("select * from retail.uom where tenant_id=? order by name",r.tenant(a)),"conversions",r.db.queryForList("select c.*,s.code,s.name as product,u.name as unit,s.unit as base_unit from retail.uom_conversion c join retail.sku s on s.tenant_id=c.tenant_id and s.id=c.product_id join retail.uom u on u.tenant_id=c.tenant_id and u.id=c.uom_id where c.tenant_id=? order by s.code,u.name",r.tenant(a)));}
  @PostMapping("/uom-conversions") Object saveUomConversion(Authentication a,@RequestBody JsonNode x,@RequestHeader("Idempotency-Key") String key){return commands.execute(a,key,"UOM_CONVERSION",x,()->{r.require(a,"SETUP");var t=r.tenant(a);var product=uuid(x,"productId");var sku=r.one("sku",t,product);var unit=r.db.queryForList("select * from retail.uom where tenant_id=? and id=?",t,uuid(x,"uomId"));if(unit.isEmpty())throw problem("INVALID_UOM","Đơn vị không tồn tại");var name=unit.getFirst().get("name").toString();var factor=positive(x,"factor");if(factor.scale()>4)throw problem("INVALID_UOM","Tỷ lệ tối đa 4 chữ số thập phân");if(name.equals(sku.get("unit")))throw problem("BASE_UOM","Đơn vị cơ sở luôn có tỷ lệ 1");r.db.queryForObject("select id from retail.sku where tenant_id=? and id=? for update",UUID.class,t,product);r.db.update("update retail.sku set units=jsonb_set(units,array[?]::text[],to_jsonb(?::numeric),true) where tenant_id=? and id=?",name,factor,t,product);return Map.of("ok",true);});}
  @GetMapping("/warehouse-config") Object warehouseConfig(Authentication a){r.require(a,"SETUP");return r.db.queryForList("select * from retail.warehouse_config where tenant_id=? order by kind,code",r.tenant(a));}
  @PostMapping("/warehouse-config") Object saveWarehouseConfig(Authentication a,@RequestBody JsonNode x,@RequestHeader("Idempotency-Key") String key){return commands.execute(a,key,"WAREHOUSE_CONFIG",x,()->{r.require(a,"SETUP");var kind=required(x,"kind",30);if(!Set.of("INVENTORY","UNIT","VARIANT","BRAND","ATTRIBUTE","GROUP").contains(kind))throw problem("INVALID_CONFIG","Loại cấu hình không hợp lệ");var code=required(x,"code",60);var name=required(x,"name",160);var value=text(x,"value","");if(value.length()>1000)throw problem("INVALID_CONFIG","Nội dung tối đa 1000 ký tự");if(kind.equals("INVENTORY")&&(!code.equals("defaultTracking")||!Set.of("NONE","LOT","SERIAL").contains(value)))throw problem("INVALID_CONFIG","Kiểu theo dõi không hợp lệ");if(kind.equals("UNIT")){if(name.length()>40)throw problem("INVALID_UOM","Tên đơn vị tối đa 40 ký tự");r.db.update("insert into retail.uom(tenant_id,name) values(?,?) on conflict do nothing",r.tenant(a),name);}r.db.update("insert into retail.warehouse_config(id,tenant_id,kind,code,name,value,active) values(?,?,?,?,?,?,?) on conflict(tenant_id,kind,code) do update set name=excluded.name,value=excluded.value,active=excluded.active",UUID.randomUUID(),r.tenant(a),kind,code,name,value,x.path("active").asBoolean(true));return Map.of("ok",true);});}
  @GetMapping("/catalog") Object catalog(Authentication a){return catalog.catalog(a);}
  @PostMapping("/catalog/{kind}") Object createCatalog(Authentication a,@PathVariable String kind,@RequestBody JsonNode x,@RequestHeader("Idempotency-Key") String key){return commands.execute(a,key,"CATALOG_"+kind,x,()->catalog.create(a,kind,x));}
  @PostMapping("/catalog/{kind}/{id}/deactivate") Object deactivate(Authentication a,@PathVariable String kind,@PathVariable UUID id,@RequestBody JsonNode x,@RequestHeader("Idempotency-Key") String key){return commands.execute(a,key,"DEACTIVATE_"+kind+"_"+id,x,()->catalog.deactivate(a,kind,id));}
  @PostMapping("/price") Object price(Authentication a,@RequestBody JsonNode x){r.require(a,"SELL");var w=r.warehouse(a,uuid(x,"warehouseId"));return catalog.price(a,uuid(x,"skuId"),optional(x,"partnerId"),(UUID)w.get("branch_id"),text(x,"channel","COUNTER"),positive(x,"qty"));}
  @GetMapping("/documents") Object documents(Authentication a,@RequestParam(defaultValue="") String type,@RequestParam(defaultValue="") String status,@RequestParam(defaultValue="") String q,@RequestParam(defaultValue="0") int page){return documents.list(a,type,status,q,page);}
  @GetMapping("/documents/{id}") Object detail(Authentication a,@PathVariable UUID id){return documents.detail(a,id);}
  @PostMapping("/documents") Object create(Authentication a,@RequestBody JsonNode x,@RequestHeader("Idempotency-Key") String key){return commands.execute(a,key,"DOCUMENT_CREATE",x,()->documents.create(a,x));}
  @PostMapping("/documents/{id}/{action}") Object transition(Authentication a,@PathVariable UUID id,@PathVariable String action,@RequestBody JsonNode x,@RequestHeader("Idempotency-Key") String key){return commands.execute(a,key,"DOCUMENT_"+action+"_"+id,x,()->documents.transition(a,id,action,x));}
  @GetMapping("/stock") Object stock(Authentication a){return inventory.stock(a);}
  @GetMapping("/movements") Object movements(Authentication a){return inventory.movements(a);}
  @GetMapping("/tracking") Object tracking(Authentication a,@RequestParam UUID warehouseId,@RequestParam UUID skuId){r.require(a,"STOCK");r.warehouse(a,warehouseId);return Map.of("lots",r.db.queryForList("select * from retail.lot where tenant_id=? and warehouse_id=? and sku_id=? order by expiry",r.tenant(a),warehouseId,skuId),"serials",r.db.queryForList("select serial,location from retail.serial where tenant_id=? and warehouse_id=? and sku_id=? order by serial",r.tenant(a),warehouseId,skuId));}
  @GetMapping("/commissions") Object commissions(Authentication a){return commissions.list(a);}
  @PostMapping("/commissions") Object commission(Authentication a,@RequestBody JsonNode x,@RequestHeader("Idempotency-Key") String key){return commands.execute(a,key,"COMMISSION_CREATE",x,()->commissions.create(a,x));}
  @GetMapping("/finance") Object finance(Authentication a){return finance.overview(a);}
  @PostMapping("/payments") Object payment(Authentication a,@RequestBody JsonNode x,@RequestHeader("Idempotency-Key") String key){return commands.execute(a,key,"PAYMENT_CREATE",x,()->finance.createPayment(a,x));}
  @PostMapping("/allocations") Object allocation(Authentication a,@RequestBody JsonNode x,@RequestHeader("Idempotency-Key") String key){r.require(a,"FINANCE");return commands.execute(a,key,"ALLOCATION",x,()->finance.allocate(a,uuid(x,"paymentId"),uuid(x,"openItemId"),num(x,"amount",java.math.BigDecimal.ZERO)));}
  @GetMapping("/deliveries") Object deliveries(Authentication a){return operations.deliveries(a);}
  @PostMapping("/deliveries") Object createDelivery(Authentication a,@RequestBody JsonNode x,@RequestHeader("Idempotency-Key") String key){return commands.execute(a,key,"DELIVERY_CREATE",x,()->operations.createDelivery(a,x));}
  @PostMapping("/deliveries/{id}/{action}") Object delivery(Authentication a,@PathVariable UUID id,@PathVariable String action,@RequestBody JsonNode x,@RequestHeader("Idempotency-Key") String key){return commands.execute(a,key,"DELIVERY_"+action+"_"+id,x,()->operations.delivery(a,id,action,x));}
  @GetMapping("/customers/{id}/history") Object history(Authentication a,@PathVariable UUID id){return operations.care(a,id);}
  @PostMapping("/care") Object care(Authentication a,@RequestBody JsonNode x,@RequestHeader("Idempotency-Key") String key){return commands.execute(a,key,"CARE_CREATE",x,()->operations.createCare(a,x));}
  @PostMapping("/care/{id}/complete") Object completeCare(Authentication a,@PathVariable UUID id,@RequestBody JsonNode x,@RequestHeader("Idempotency-Key") String key){return commands.execute(a,key,"CARE_COMPLETE_"+id,x,()->operations.completeCare(a,id));}
  @GetMapping("/original-sale") Object original(Authentication a,@RequestParam String number){return operations.lookupOriginal(a,number);}
  @GetMapping("/warranties") Object warranties(Authentication a){return operations.warrantyList(a);}
  @PostMapping("/warranties") Object warranty(Authentication a,@RequestBody JsonNode x,@RequestHeader("Idempotency-Key") String key){return commands.execute(a,key,"WARRANTY_CREATE",x,()->operations.warranty(a,x));}
  @PostMapping("/warranties/{id}/status") Object warrantyStatus(Authentication a,@PathVariable UUID id,@RequestBody JsonNode x,@RequestHeader("Idempotency-Key") String key){return commands.execute(a,key,"WARRANTY_STATUS_"+id,x,()->operations.warrantyStatus(a,id,x));}
  @GetMapping("/summary") Object summary(Authentication a){return operations.summary(a);}
  @GetMapping("/reports") Object report(Authentication a,@RequestParam String from,@RequestParam String to){return operations.report(a,from,to);}
  @PostMapping("/imports") Object preview(Authentication a,@RequestBody JsonNode x,@RequestHeader("Idempotency-Key") String key){return commands.execute(a,key,"IMPORT_PREVIEW",x,()->imports.preview(a,x));}
  @PostMapping("/imports/file") Object file(Authentication a,@RequestParam String kind,@RequestParam UUID warehouseId,@RequestParam MultipartFile file,@RequestHeader("Idempotency-Key") String key)throws java.io.IOException{r.require(a,"SETUP");var x=r.json.createObjectNode().put("kind",kind).put("warehouseId",warehouseId.toString());x.set("rows",imports.parse(file.getBytes(),file.getOriginalFilename()==null?"":file.getOriginalFilename()));return commands.execute(a,key,"IMPORT_PREVIEW",x,()->imports.preview(a,x));}
  @PostMapping("/imports/{id}/commit") Object commit(Authentication a,@PathVariable UUID id,@RequestBody JsonNode x,@RequestHeader("Idempotency-Key") String key){return commands.execute(a,key,"IMPORT_COMMIT_"+id,x,()->imports.commit(a,id));}
  @GetMapping("/imports") Object batches(Authentication a){r.require(a,"SETUP");return r.db.queryForList("select * from retail.import_batch b where tenant_id=? and "+r.scope(a,"b")+" order by created_at desc limit 100",r.tenant(a)).stream().map(r::clean).toList();}
  @GetMapping("/scopes") Object scopes(Authentication a){r.require(a,"SETUP");return r.db.queryForList("select s.*,a.email,w.name warehouse from retail.access_scope s join identity.account a on a.id=s.account_id join retail.warehouse w on w.tenant_id=s.tenant_id and w.id=s.warehouse_id where s.tenant_id=? and "+r.scope(a,"s"),r.tenant(a));}
  @GetMapping("/export") ResponseEntity<String> export(Authentication a,@RequestParam String kind,@RequestParam(defaultValue="") String from,@RequestParam(defaultValue="") String to){r.require(a,"EXPORT");List<Map<String,Object>> rows=(List<Map<String,Object>>)commands.export(a,kind,()->switch(kind){case "suppliers"->r.db.queryForList("select code,name,phone,email,address,active from retail.partner where tenant_id=? and kind='SUPPLIER' order by code",r.tenant(a));case "products"->(List<Map<String,Object>>)((Map<?,?>)catalog.catalog(a)).get("skus");case "stock"->(List<Map<String,Object>>)inventory.stock(a);case "movements"->(List<Map<String,Object>>)inventory.movements(a);case "documents"->allDocuments(a);case "payments"->(List<Map<String,Object>>)((Map<?,?>)finance.overview(a)).get("payments");case "finance"->(List<Map<String,Object>>)((Map<?,?>)finance.overview(a)).get("openItems");case "report"->(List<Map<String,Object>>)((Map<?,?>)operations.report(a,from,to)).get("sales");default->throw problem("EXPORT_KIND","Loại xuất không hợp lệ");});var csv=new StringBuilder("\ufeff");if(!rows.isEmpty()){var columns=new ArrayList<>(rows.getFirst().keySet());csv.append(String.join(",",columns)).append("\r\n");for(var row:rows){csv.append(columns.stream().map(c->escape(row.get(c))).collect(java.util.stream.Collectors.joining(","))).append("\r\n");}}return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=aicrm-"+kind+".csv").contentType(new MediaType("text","csv",java.nio.charset.StandardCharsets.UTF_8)).body(csv.toString());}
  private List<Map<String,Object>> allDocuments(Authentication a){var rows=new ArrayList<Map<String,Object>>();int page=0;while(true){var result=(Map<?,?>)documents.list(a,"","","",page++);var items=(List<Map<String,Object>>)result.get("items");rows.addAll(items);if(items.size()<50)break;}return rows;}
  private String escape(Object value){String text=value==null?"":value.toString();if(text.matches("^[=+@\\-].*"))text="'"+text;return "\""+text.replace("\"","\"\"")+"\"";}
}
